html.login-html body.cms-theme {
  min-width: 320px;
  min-height: 100%;
  margin: 0;
  background:
    radial-gradient(circle at 10% 12%, rgba(0, 80, 153, 0.08), transparent 24rem),
    rgb(246, 244, 239) !important;
  color: rgb(80, 75, 70);
}

.login-page {
  --login-main: rgb(0, 80, 153);
  --login-main-hover: rgb(0, 101, 194);
  --login-white: rgb(255, 255, 255);
  --login-page: rgb(246, 244, 239);
  --login-panel: rgb(251, 250, 247);
  --login-text-light: rgb(115, 110, 105);
  --login-text-dark: rgb(80, 75, 70);
  --login-border: rgba(94, 111, 109, 0.32);
  --login-focus: rgba(0, 80, 153, 0.18);
  min-height: 100vh;
  padding: 18px;
  display: grid;
  place-items: center;
}

.login-shell {
  width: 100%;
  max-width: 560px;
  min-height: 680px;
  display: grid;
  overflow: hidden;
  border: 1px solid rgba(0, 80, 153, 0.12);
  background: var(--login-white);
  box-shadow: 0 28px 70px rgba(32, 58, 83, 0.15);
}

.login-panel {
  min-height: 100%;
  display: flex;
  flex-direction: column;
  background: var(--login-panel);
}

.login-panel__inner {
  width: 100%;
  max-width: 410px;
  margin: auto;
  padding: 52px 32px 38px;
}

.login-logo {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  color: var(--login-main);
  text-decoration: none;
}

.login-logo:hover {
  color: var(--login-main);
  text-decoration: none;
}

.login-logo__mark {
  width: 43px;
  height: 43px;
  display: grid;
  place-items: center;
  overflow: hidden;
  border: 1px solid var(--login-main);
  background: var(--login-white);
}

.login-logo__mark img {
  width: 36px;
  height: 36px;
  object-fit: contain;
}

.login-logo strong,
.login-logo small {
  display: block;
}

.login-logo strong {
  font-family: "Times New Roman", serif;
  font-size: 18px;
  letter-spacing: 0.08em;
  line-height: 1.1;
}

.login-logo small {
  margin-top: 4px;
  color: var(--login-text-light);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.17em;
}

.login-heading {
  margin: 70px 0 38px;
}

.login-heading p {
  margin: 0 0 10px;
  color: var(--login-main);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.18em;
  text-transform: uppercase;
}

.login-heading h2 {
  margin: 0 0 14px;
  color: var(--login-text-dark);
  font-family: "Times New Roman", serif;
  font-size: 36px;
  font-weight: 400;
  letter-spacing: -0.025em;
  line-height: 1.2;
}

.login-heading span {
  color: var(--login-text-light);
  font-size: 15px;
  line-height: 1.65;
}

.login-form {
  display: grid;
  gap: 23px;
}

.form-field label,
.form-field__label-row {
  color: var(--login-text-dark);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.form-field > label,
.form-field__label-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 10px;
}

.form-field__label-row a {
  color: var(--login-main);
  font-size: 11px;
  letter-spacing: 0.03em;
  text-decoration: none;
  text-transform: none;
}

.form-field__label-row a:hover,
.login-support a:hover {
  text-decoration: underline;
}

.form-field__control {
  position: relative;
}

.form-field__icon {
  position: absolute;
  z-index: 1;
  top: 50%;
  left: 18px;
  width: 19px;
  height: 19px;
  color: var(--login-main);
  transform: translateY(-50%);
  pointer-events: none;
}

.form-field__icon svg,
.login-button svg {
  width: 100%;
  height: 100%;
  fill: none;
  stroke: currentColor;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: 1.7;
}

.login-page .form-field input[type="text"],
.login-page .form-field input[type="password"] {
  width: 100% !important;
  height: 58px !important;
  padding: 10px 18px 10px 50px !important;
  border: 1px solid var(--login-border) !important;
  border-radius: 0 !important;
  outline: none !important;
  background: var(--login-white) !important;
  color: var(--login-text-dark) !important;
  font-size: 15px !important;
  box-shadow: none !important;
}

.login-page .form-field input::placeholder {
  color: rgba(115, 110, 105, 0.68);
}

.login-page .form-field input:focus {
  border-color: var(--login-main) !important;
  box-shadow: 0 0 0 4px var(--login-focus) !important;
}

.login-message {
  display: none;
  margin: 0;
  color: #b42318;
  font-size: 13px;
  line-height: 1.5;
}

.login-message.login-message--show {
  display: block;
}

.remember-option,
.login-page span.remember-option {
  width: max-content;
  display: inline-flex !important;
  align-items: center;
  gap: 10px;
  color: var(--login-text-light);
  cursor: pointer;
  font-size: 14px;
}

.login-page .remember-option input,
.login-page span.remember-option input {
  width: 17px;
  height: 17px;
  margin: 0;
  accent-color: var(--login-main);
}

.login-page .remember-option label,
.login-page span.remember-option label {
  margin: 0;
  color: var(--login-text-light);
  font-size: 14px;
  font-weight: 400;
  letter-spacing: 0;
  text-transform: none;
}

.login-button {
  width: 100%;
  min-height: 58px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  border: 1px solid var(--login-main);
  border-radius: 0;
  background: var(--login-main);
  color: var(--login-white) !important;
  cursor: pointer;
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.13em;
  text-transform: uppercase;
  text-decoration: none !important;
  transition: background-color 180ms ease, box-shadow 180ms ease, transform 180ms ease;
}

.login-button svg {
  width: 19px;
  height: 19px;
}

.login-button:hover {
  background: var(--login-main-hover);
  color: var(--login-white) !important;
  box-shadow: 0 10px 24px rgba(0, 80, 153, 0.22);
  transform: translateY(-1px);
  text-decoration: none !important;
}

.login-support {
  margin: 30px 0 0;
  color: var(--login-text-light);
  font-size: 13px;
  line-height: 1.5;
  text-align: center;
}

.login-support a {
  color: var(--login-main);
  font-weight: 600;
  text-decoration: none;
}

.login-footer {
  display: flex;
  justify-content: space-between;
  gap: 20px;
  padding: 22px 38px;
  border-top: 1px solid rgba(94, 111, 109, 0.16);
  color: rgba(115, 110, 105, 0.75);
  font-size: 10px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

@media (max-width: 900px) {
  .login-page {
    padding: 0;
  }

  .login-shell {
    min-height: 100vh;
    border: 0;
    box-shadow: none;
  }

  .login-panel__inner {
    max-width: 500px;
    padding-top: 48px;
  }

  .login-heading {
    margin-top: 48px;
  }
}

@media (max-width: 520px) {
  .login-panel__inner {
    padding-left: 20px;
    padding-right: 20px;
  }

