namespace InformationWeb.Controls.SimsMember
{
    public partial class MemberArea : System.Web.UI.UserControl
    {
        #region Variables

        private string strRegisterPage = "";
        private string strForgetPassPage = "";
        private string strProfilePage = "";

        #endregion

        #region Properties

        public string ForgetPassPage
        {
            get { return strForgetPassPage; }
            set { strForgetPassPage = value; }
        }

        public string ProfilePage
        {
            get { return strProfilePage; }
            set { strProfilePage = value; }
        }

        #endregion

        /// <summary>
        /// Kiểm tra session đăng nhập, nếu chưa đăng nhập thì chuyển sang trang Login.aspx
        /// Gọi ở bất cứ đâu vì là static
        /// </summary>
        /// <param name="ctrl"></param>
        public static bool CheckLoginStatus(System.Web.UI.UserControl ctrl)
        {
            if (WebGlobal.User == null)
            {
                HttpContext.Current.Response.Redirect("~/Login.aspx");
                return false;
            }
            return true;
        }

        public void ShowStatus()
        {
            if (WebGlobal.User != null)
            {
                ulLogin.Visible = false;
                ulUser.Visible = true;
                lblLoginUser.Text = WebGlobal.User.FullName;
            }
            else
            {
                ulLogin.Visible = true;
                ulUser.Visible = false;
            }
            UpdatePanel1.Update();
        }

        protected void Page_Load(object sender, EventArgs e)
        {
            if (!IsPostBack)
            {
                ShowStatus();
            }
        }

        #region Event

        protected void lbtLogout_Click(object sender, EventArgs e)
        {
            WebGlobal.User = null;
            WebGlobal.StudentID = 0;
            WebGlobal.ClassID = null;
            Response.Redirect("~/Login.aspx");
        }

        protected void lbtChangeProfile_Click(object sender, EventArgs e)
        {
            if (this.strProfilePage.Trim() != "")
                Response.Redirect(DCore.Globals.ApplicationVRoot + "/" + strProfilePage);
            else
                Response.Redirect(DCore.Globals.ApplicationVRoot + "/Pages/SimsMember/ChangeProfile.aspx");
        }

        #endregion

    }
}

